package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.model.artisan.contact.ContactResponseimport com.dy.artisan3d.domain.repository.ContactUsRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.safeApiCallimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.forms.MultiPartFormDataContentimport io.ktor.client.request.forms.formDataimport io.ktor.client.request.postimport io.ktor.client.request.setBodyclass ContactUsRepositoryImpl(    private val httpClient: HttpClient): ContactUsRepository {    override suspend fun sendContactUs(        fullName: String,        email: String,        message: String,    ): Result<ContactResponse> {        return safeApiCall {            val url = BASE_URL + "contact"            httpClient.post(url) {                setBody(                    MultiPartFormDataContent(                        formData {                            append("full_name", fullName)                            append("access", email)                            append("message", message)                        }                    )                )            }.body<ContactResponse>()        }    }}